sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    /*** Storing the current and previous value of field from the Business Process Instance record ***/
    var previousStockEventStatus = previous.stock_stage_reference;
    var currentStockEventStatus = current.stock_stage_reference;
    var tradeIDValue = current.trade_id;
    var caseClosureCheck = current.stock_stage_reference.previous_case_closure_stage;
    var caseQuery;
    var bpDataStock = current.stock_stage_reference.business_process;
    try {
        if (currentStockEventStatus != previousStockEventStatus) { // updating Business Process Stage and Custody Case table Query condition for Stock 
            caseQuery = 'active=true^trade_id=' + tradeIDValue + '^triggered_by.business_process=' + bpDataStock + '^amend_case!=True'; //amend_case is set 'True' in Amend Flow for linked case, added as part of MSSCUSTODY-6538
        }

        /***Query Case and Task only if Previpus Case Closure is true **/
        if (caseClosureCheck) {
            var grCustodyCase = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_case');
            grCustodyCase.addEncodedQuery(caseQuery);
            grCustodyCase.query();
            while (grCustodyCase.next()) {
                var grFlow = new GlideRecord('sys_flow_context'); // Cancelling the flow context when the case closure happens as part of FOL event
                grFlow.addQuery('source_record', grCustodyCase.sys_id);
                grFlow.query();
                while (grFlow.next()) {
                    sn_fd.FlowAPI.cancel(grFlow.sys_id, 'Cancelling active flows for active false custody cases');
                }
                grCustodyCase.state = 3; // Updating state of  the Case to "Closed Complete" after either closing or cancelling the task
                grCustodyCase.update();
            }
            current.is_case_created_stock = false; // Set flag to false
        }

    } catch (ex) {
        gs.addInfoMessage(ex.message);
    }



})(current, previous);
